/**
 * The contract both `textarea.tsx` (native) and `textarea.web.tsx` implement.
 *
 * It lives in its own module for the same reason `input-base.ts` does: Metro
 * resolves `./textarea` to `textarea.web.tsx` on web, so the web file importing
 * the shared pieces from `./textarea` would be importing itself.
 *
 * The props are spelled out rather than taken from `TextInputProps` because
 * callers write `onChangeText`, not a DOM change event — the same contract
 * `input-base.ts` holds, so a bound field looks identical whichever it wraps.
 */

import type { Ref } from "react";

/**
 * What a caller may do to the box imperatively: put the caret back after a send. On the web the
 * ref is the `<textarea>` itself, which has `focus`, as `InputHandle` is the `<input>` there.
 */
export type TextareaHandle = { focus: () => void };

/**
 * What `onKeyPress` hands over, as on `Input`: the key, as `nativeEvent.key`. The other two are
 * what Enter-to-send reads, and only a keyboard with a Shift to hold reports them, so they are
 * there on the web and absent on a device. Declared here and not taken from `input-base.ts`, so
 * this item installs without that one.
 */
export type TextareaKeyPressEvent = {
  nativeEvent: {
    key: string;
    shiftKey?: boolean | undefined;
    isComposing?: boolean | undefined;
  };
};

/** A handler of that event, as a method so a narrower native handler is still accepted. */
export type TextareaKeyPressHandler = {
  bivarianceHack(event: TextareaKeyPressEvent): void;
}["bivarianceHack"];

/**
 * Whether a key sends. Enter alone: Shift+Enter is a new line, and an Enter that only accepts
 * an input method's suggestion is still someone part-way through a word.
 */
export function isSubmitKey({
  key,
  shiftKey,
  isComposing,
}: TextareaKeyPressEvent["nativeEvent"]): boolean {
  return key === "Enter" && shiftKey !== true && isComposing !== true;
}

/** Where the caret is, as offsets into the text. A caret with nothing selected has the two equal. */
export type TextareaSelection = { start: number; end: number };

export type TextareaProps = {
  value?: string | undefined;
  /** Uncontrolled: where the text starts, when nothing above is holding `value`. */
  defaultValue?: string | undefined;
  onChangeText?: ((text: string) => void) | undefined;
  onBlur?: (() => void) | undefined;
  /**
   * Enter without Shift, which is what sends a chat message; Shift+Enter is still a new line.
   * Where there is a Shift to hold, that is: the web, an Expo app's web build included. On a
   * device the return key adds a line, as it does in every messaging app, and a send button is
   * the way out.
   */
  onSubmitEditing?: (() => void) | undefined;
  /**
   * Holds the caret, as `TextInput`'s does: the way to put it after a name a completion has just
   * inserted. Controlled, so keep it in step from `onSelectionChange` or it pins the caret.
   */
  selection?: TextareaSelection | undefined;
  /**
   * The caret moved, or the selection changed: by a key, a click, or the text changing under it.
   * What an `@mention` menu reads to find the word the caret is in, wherever in the note that is.
   */
  onSelectionChange?: ((selection: TextareaSelection) => void) | undefined;
  /** Every key as it goes down, as on `Input`. */
  onKeyPress?: TextareaKeyPressHandler | undefined;
  /** Escape, after any `onKeyPress`. A soft keyboard has no such key. */
  onEscape?: (() => void) | undefined;
  placeholder?: string | undefined;
  /**
   * Visible lines; the box grows no further and scrolls instead. With `maxRows` it is where the
   * box starts, one line when left out.
   */
  rows?: number | undefined;
  /**
   * Makes the box grow with its text: from `rows` up to this many lines, and scrolling past
   * them. A chat composer is `rows={1} maxRows={6}`. It shrinks again when the text does, so a
   * message that was sent leaves a one-line box behind.
   */
  maxRows?: number | undefined;
  maxLength?: number | undefined;
  disabled?: boolean | undefined;
  /** Takes focus when it mounts, as `Input`'s does: a reply box that opens ready to type in. */
  autoFocus?: boolean | undefined;
  className?: string | undefined;
  /** Web only: ties the control to its `<label>`. */
  id?: string | undefined;
  ref?: Ref<TextareaHandle> | undefined;
};

/** A line of `text-sm`, and the `py-2` above and below the text, in pixels. */
const LINE_HEIGHT = 20;
const PADDING = 16;

/** How tall the box is at a number of rows, border left out. */
export function rowsHeight(rows: number): number {
  return rows * LINE_HEIGHT + PADDING;
}

/** The part of a `<textarea>` that `fitRows` reads and writes. */
export type GrowingBox = {
  style: { height: string; overflowY: string };
  scrollHeight: number;
  offsetHeight: number;
  clientHeight: number;
};

/**
 * Sizes a `<textarea>` to its text, held between two numbers of rows.
 *
 * The height is let go first, because `scrollHeight` is never less than the box: a box left at
 * six lines would report six lines for ever, and never shrink after a send. The scrollbar is
 * only allowed once the cap is reached, so it does not flash in and out as a line is added.
 */
export function fitRows(box: GrowingBox, minRows: number, maxRows: number): void {
  const border = box.offsetHeight - box.clientHeight;
  box.style.height = "auto";
  const text = box.scrollHeight;
  const max = rowsHeight(Math.max(minRows, maxRows));
  const height = Math.min(Math.max(text, rowsHeight(minRows)), max);
  box.style.height = `${height + border}px`;
  box.style.overflowY = text > max ? "auto" : "hidden";
}

/**
 * The placeholder colour rides here as a `placeholder:` variant, the same way
 * `INPUT_CLASS` does it. NativeWind 4's `placeholderClassName` prop is gone in
 * 5; the variant compiles to `placeholderTextColor` on device and to a real
 * `::placeholder` rule on web.
 */
export const TEXTAREA_CLASS =
  "border-foreground/15 bg-background text-foreground placeholder:text-foreground/60 focus:border-active min-h-[80px] w-full rounded-md border px-3 py-2 text-sm focus:outline-none";

/**
 * Multi-line text entry on device — see `textarea-base.ts` for the contract both
 * halves implement, and `textarea.web.tsx` for the other one.
 *
 * This file used to be the whole item: a `TextInput multiline` is a real
 * `<textarea>` under react-native-web, so a web half looked like pure
 * duplication. The compiled registry is what made that false — it ships to the
 * DOM with no react-native-web underneath, so there is no longer anything to do
 * the swap. `rn2web` refused the item and said so, which is how the gap surfaced
 * rather than shipping as a `<div>` nobody could type into.
 */

import { useImperativeHandle, useLayoutEffect, useRef } from "react";
import { Platform, TextInput } from "react-native";
import {
  fitRows,
  type GrowingBox,
  isSubmitKey,
  rowsHeight,
  TEXTAREA_CLASS,
  type TextareaHandle,
  type TextareaKeyPressEvent,
  type TextareaKeyPressHandler,
  type TextareaProps,
  type TextareaSelection,
} from "@/components/ui/textarea-base";
import { cn } from "@/lib/utils";

function Textarea({
  value,
  defaultValue,
  onChangeText,
  onBlur,
  onSubmitEditing,
  selection,
  onSelectionChange,
  onKeyPress,
  onEscape,
  placeholder,
  rows,
  maxRows,
  maxLength,
  disabled,
  autoFocus,
  className,
  id,
  ref,
}: TextareaProps) {
  const inner = useRef<TextInput>(null);
  useImperativeHandle<TextareaHandle, TextareaHandle>(ref, () => ({
    focus: () => inner.current?.focus(),
  }));

  const grows = maxRows !== undefined;
  const minRows = rows ?? 1;
  // A device's multiline input grows with its text by itself, and only needs the two ends. Under
  // react-native-web the input is a `<textarea>`, which does not, so it is measured.
  const refit = () => {
    if (grows === false || Platform.OS !== "web" || !inner.current) {
      return;
    }
    fitRows(inner.current as unknown as GrowingBox, minRows, maxRows);
  };
  // After every render and not only a changed `value`: the text can also arrive as a new
  // `defaultValue`, and the box can change width under it.
  useLayoutEffect(refit);

  return (
    <TextInput
      ref={inner}
      multiline
      textAlignVertical="top"
      // Held at `""` unless the caller asked for uncontrolled by passing a `defaultValue`: a bound
      // field's value starts `undefined` more often than not.
      {...(defaultValue === undefined ? { value: value ?? "" } : { value, defaultValue })}
      onChangeText={(text) => {
        onChangeText?.(text);
        // An uncontrolled box does not render again on a keystroke.
        refit();
      }}
      onBlur={onBlur}
      {...(selection !== undefined ? { selection } : {})}
      {...(onSelectionChange
        ? { onSelectionChange: (event) => onSelectionChange(event.nativeEvent.selection) }
        : {})}
      {...(autoFocus !== undefined ? { autoFocus } : {})}
      onKeyPress={(event) => {
        onKeyPress?.(event);
        if (event.nativeEvent.key === "Escape") {
          onEscape?.();
        }
        // Only where the key reports its Shift. A device's return key does not, and taking it
        // would leave a message with no way to hold a second line.
        if (Platform.OS === "web" && onSubmitEditing && isSubmitKey(event.nativeEvent)) {
          // Held back, or the Enter that sent the message would also add a line to the next.
          event.preventDefault();
          onSubmitEditing();
        }
      }}
      placeholder={placeholder}
      // Not while it grows: Android reads `numberOfLines` as the height, not as where it starts.
      {...(rows !== undefined && grows === false ? { numberOfLines: rows } : {})}
      {...(maxLength !== undefined ? { maxLength } : {})}
      editable={!disabled}
      id={id}
      {...(grows && Platform.OS !== "web"
        ? { style: { minHeight: rowsHeight(minRows), maxHeight: rowsHeight(maxRows) } }
        : {})}
      // `min-h-0` lets go of the class's 80px floor, which is four lines a composer starts without.
      className={cn(TEXTAREA_CLASS, grows && "min-h-0", disabled && "opacity-50", className)}
    />
  );
}

export type {
  TextareaHandle,
  TextareaKeyPressEvent,
  TextareaKeyPressHandler,
  TextareaProps,
  TextareaSelection,
};
export { Textarea };

/**
 * The web implementation — see `textarea.tsx` for why this one is split, and
 * `textarea-base.ts` for the contract both sides implement.
 *
 * It is hand-written rather than compiled because nothing `TextInput` does here
 * survives a rename table: `editable={!disabled}` inverts, `onChangeText(text)`
 * and `onChange(event)` are different signatures, and the element itself depends
 * on the value of `multiline`. Each of those is the compiler guessing at
 * semantics the source never stated, which is the one thing it is built not to
 * do — so it refuses, and this file is the answer it asks for.
 *
 * **It is also shadcn's `Textarea`.** It installs over a DOM app's own
 * `components/ui/textarea.tsx`, so it takes everything a `<textarea>` does —
 * `onChange(event)` beside `onChangeText`, `name`, `defaultValue`, the key and
 * focus handlers, a `ref` to the element — and a `value` left out is left
 * uncontrolled, as it is on the DOM. (The native half holds a missing value at
 * `""`; a bound field passes one either way.)
 */

import {
  type ComponentPropsWithoutRef,
  type KeyboardEventHandler,
  type Ref,
  useLayoutEffect,
  useRef,
} from "react";
import {
  fitRows,
  isSubmitKey,
  type TextareaProps as SharedTextareaProps,
  TEXTAREA_CLASS,
  type TextareaHandle,
  type TextareaKeyPressEvent,
  type TextareaKeyPressHandler,
  type TextareaSelection,
} from "@/components/ui/textarea-base";
import { cn } from "@/lib/utils";

/**
 * The shared contract, widened to everything a DOM `<textarea>` takes. `onKeyPress` hands over
 * the React keyboard event, which is a shared handler's `{ nativeEvent: { key } }` and a shadcn
 * call site's `e.key` at once, and the ref is the element, which is a `TextareaHandle` too.
 */
export type TextareaProps = Omit<ComponentPropsWithoutRef<"textarea">, "className" | "onKeyPress"> &
  Omit<SharedTextareaProps, "onBlur" | "value" | "onKeyPress" | "ref"> & {
    value?: ComponentPropsWithoutRef<"textarea">["value"];
    onKeyPress?: KeyboardEventHandler<HTMLTextAreaElement> | undefined;
    ref?: Ref<HTMLTextAreaElement> | Ref<TextareaHandle> | undefined;
  };

function Textarea({
  onChange,
  onChangeText,
  onSelect,
  selection,
  onSelectionChange,
  onKeyDown,
  onKeyPress,
  onSubmitEditing,
  onEscape,
  rows,
  maxRows,
  className,
  ref,
  ...props
}: TextareaProps) {
  const inner = useRef<HTMLTextAreaElement | null>(null);
  const grows = maxRows !== undefined;
  const minRows = rows ?? 1;
  const refit = () => {
    if (grows && inner.current) {
      fitRows(inner.current, minRows, maxRows);
    }
  };
  // After every render and not only a changed `value`: the text can also arrive as a new
  // `defaultValue`, and the box can change width under it.
  useLayoutEffect(refit);

  // The caret is the element's own, so a held `selection` is written to it after each render,
  // once the new text is in the box and there is somewhere to put it.
  const start = selection?.start;
  const end = selection?.end;
  useLayoutEffect(() => {
    const box = inner.current;
    if (!box || start === undefined || end === undefined) {
      return;
    }
    if (box.selectionStart !== start || box.selectionEnd !== end) {
      box.setSelectionRange(start, end);
    }
  });

  // Told once per change. React's `select` covers the keys and the pointer but arrives a keyup
  // after the text, and a menu reading both would see the new text with the old caret between.
  const reported = useRef<TextareaSelection | null>(null);
  const report = (box: HTMLTextAreaElement) => {
    if (!onSelectionChange) {
      return;
    }
    const next = { start: box.selectionStart, end: box.selectionEnd };
    if (reported.current?.start === next.start && reported.current.end === next.end) {
      return;
    }
    reported.current = next;
    onSelectionChange(next);
  };

  return (
    <textarea
      // The element is the handle: it has `focus`, which is all `TextareaHandle` asks. It is kept
      // here too, to be measured.
      ref={(element) => {
        inner.current = element;
        const outer = ref as Ref<HTMLTextAreaElement> | undefined;
        if (typeof outer === "function") {
          return outer(element);
        }
        if (outer) {
          outer.current = element;
        }
      }}
      data-slot="textarea"
      rows={grows ? minRows : rows}
      onChange={(e) => {
        onChange?.(e);
        onChangeText?.(e.target.value);
        // An uncontrolled box does not render again on a keystroke.
        refit();
        report(e.target);
      }}
      onSelect={(e) => {
        onSelect?.(e);
        report(e.currentTarget);
      }}
      onKeyDown={(e) => {
        onKeyDown?.(e);
        // `keydown`, not the DOM's `keypress`, which never fires for Escape. As `Input` does.
        onKeyPress?.(e);
        if (e.defaultPrevented) {
          return;
        }
        if (onSubmitEditing && isSubmitKey(e.nativeEvent)) {
          // Held back, or the Enter that sent the message would also add a line to the next.
          e.preventDefault();
          onSubmitEditing();
        } else if (e.key === "Escape") {
          onEscape?.();
        }
      }}
      {...props}
      className={cn(
        TEXTAREA_CLASS,
        // `resize-y` is the browser's own affordance and has no native
        // counterpart; `disabled:` is the DOM attribute doing what the native
        // half spells out as `disabled && "opacity-50"`.
        "resize-y disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-negative aria-invalid:focus:border-active",
        // A box that sizes itself has no corner to drag, and lets go of the class's 80px floor.
        grows && "min-h-0 resize-none",
        className,
      )}
    />
  );
}

export type { TextareaHandle, TextareaKeyPressEvent, TextareaKeyPressHandler, TextareaSelection };
export { Textarea };
